/**
 * codex F3 critical test: real Chromium navigates through the SOCKS5 bridge.
 *
 * The other bridge tests prove TCP relay works at the byte level. This test
 * proves the FEATURE works: a Chromium browser launched with
 * proxy.server = 'socks5://127.0.0.1:<bridgePort>' actually traverses the
 * bridge → authenticated upstream → destination chain. Without this test,
 * we could ship a working transport layer and a broken integration with
 * Chromium and not know it.
 */

import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
import { chromium, type Browser } from 'playwright';
import * as net from 'net';
import * as http from 'http';
import { startSocksBridge, type BridgeHandle } from '../src/socks-bridge';

interface MockUpstream {
  port: number;
  close: () => Promise<void>;
  totalConnects: () => number;
}

/**
 * Minimal SOCKS5 upstream with username/password auth. Tracks how many
 * CONNECT requests succeeded — non-zero proves the browser's request
 * actually traversed the chain.
 */
async function startAuthUpstream(user: string, pass: string): Promise<MockUpstream> {
  let connects = 0;
  const server = net.createServer((sock) => {
    sock.once('data', (greeting) => {
      if (greeting[0] !== 0x05) { sock.destroy(); return; }
      const methods = greeting.subarray(2, 2 + greeting[1]);
      if (!methods.includes(0x02)) { sock.write(Buffer.from([0x05, 0xFF])); sock.destroy(); return; }
      sock.write(Buffer.from([0x05, 0x02]));
      sock.once('data', (auth) => {
        const ulen = auth[1];
        const uname = auth.subarray(2, 2 + ulen).toString();
        const plen = auth[2 + ulen];
        const passwd = auth.subarray(3 + ulen, 3 + ulen + plen).toString();
        if (uname !== user || passwd !== pass) {
          sock.write(Buffer.from([0x01, 0x01])); sock.destroy(); return;
        }
        sock.write(Buffer.from([0x01, 0x00]));
        sock.once('data', (req) => {
          const atyp = req[3];
          let host: string; let port: number;
          if (atyp === 0x01) {
            host = `${req[4]}.${req[5]}.${req[6]}.${req[7]}`;
            port = req.readUInt16BE(8);
          } else if (atyp === 0x03) {
            const len = req[4];
            host = req.subarray(5, 5 + len).toString();
            port = req.readUInt16BE(5 + len);
          } else {
            sock.write(Buffer.from([0x05, 0x08, 0x00, 0x01, 0, 0, 0, 0, 0, 0]));
            sock.destroy(); return;
          }
          const dest = net.createConnection({ host, port }, () => {
            connects++;
            sock.write(Buffer.from([0x05, 0x00, 0x00, 0x01, 0, 0, 0, 0, 0, 0]));
            sock.pipe(dest);
            dest.pipe(sock);
            sock.on('error', () => dest.destroy());
            dest.on('error', () => sock.destroy());
            sock.on('close', () => dest.destroy());
            dest.on('close', () => sock.destroy());
          });
          dest.on('error', () => {
            try { sock.write(Buffer.from([0x05, 0x04, 0x00, 0x01, 0, 0, 0, 0, 0, 0])); } catch {}
            sock.destroy();
          });
        });
      });
    });
    sock.on('error', () => sock.destroy());
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.once('listening', () => resolve());
    server.listen(0, '127.0.0.1');
  });
  const addr = server.address();
  if (!addr || typeof addr === 'string') throw new Error('mock upstream: bad address');
  return {
    port: addr.port,
    totalConnects: () => connects,
    close: () => new Promise((r) => server.close(() => r())),
  };
}

/** Tiny HTTP server to serve as the navigation target. */
async function startHttpFixture(body: string): Promise<{ port: number; close: () => Promise<void>; hits: () => number }> {
  let hits = 0;
  const server = http.createServer((_req, res) => {
    hits++;
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(body);
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve());
  });
  const addr = server.address();
  if (!addr || typeof addr === 'string') throw new Error('http fixture: bad address');
  return {
    port: addr.port,
    hits: () => hits,
    close: () => new Promise((r) => server.close(() => r())),
  };
}

describe('bridge-chromium-e2e (codex F3)', () => {
  let upstream: MockUpstream;
  let bridge: BridgeHandle;
  let httpFixture: { port: number; close: () => Promise<void>; hits: () => number };
  let browser: Browser;

  beforeAll(async () => {
    upstream = await startAuthUpstream('alice', 'wonderland');
    bridge = await startSocksBridge({
      upstream: { host: '127.0.0.1', port: upstream.port, userId: 'alice', password: 'wonderland' },
    });
    httpFixture = await startHttpFixture('<html><body><h1 id="ok">via-bridge</h1></body></html>');
    browser = await chromium.launch({
      headless: true,
      proxy: { server: `socks5://127.0.0.1:${bridge.port}` },
    });
  });

  afterAll(async () => {
    await browser.close();
    await httpFixture.close();
    await bridge.close();
    await upstream.close();
  });

  test('Chromium navigates through bridge → auth upstream → HTTP fixture', async () => {
    const page = await browser.newPage();
    try {
      const before = upstream.totalConnects();
      const fixtureHitsBefore = httpFixture.hits();

      // Use 127.0.0.1 explicitly so we hit our local HTTP server (not via DNS).
      const target = `http://127.0.0.1:${httpFixture.port}/`;
      const response = await page.goto(target);
      expect(response?.ok()).toBe(true);

      const text = await page.locator('#ok').textContent();
      expect(text).toBe('via-bridge');

      // Proof of traversal: the upstream's connect counter incremented AND
      // the HTTP fixture got a hit.
      expect(upstream.totalConnects()).toBeGreaterThan(before);
      expect(httpFixture.hits()).toBeGreaterThan(fixtureHitsBefore);
    } finally {
      await page.close();
    }
  });

  test('subsequent navigation also traverses the bridge', async () => {
    const page = await browser.newPage();
    try {
      const before = upstream.totalConnects();
      const target = `http://127.0.0.1:${httpFixture.port}/page2`;
      await page.goto(target);
      expect(upstream.totalConnects()).toBeGreaterThan(before);
    } finally {
      await page.close();
    }
  });
});

describe('bridge-port-restart (codex F1, reframed)', () => {
  test('two sequential bridge instances pick different ephemeral ports', async () => {
    // codex F1: the original bridge-port-isolation test assumed two browse
    // daemons coexist, which contradicts our single-daemon refuse-on-mismatch
    // model (D2). The valid restart test is: spin up bridge A, close it,
    // spin up bridge B, assert B picks a fresh ephemeral port (and that a
    // hardcoded port like 1090 never appears in either).
    const upstream = await startAuthUpstream('u', 'p');
    try {
      const a = await startSocksBridge({
        upstream: { host: '127.0.0.1', port: upstream.port, userId: 'u', password: 'p' },
      });
      expect(a.port).not.toBe(1090);
      const portA = a.port;
      await a.close();

      const b = await startSocksBridge({
        upstream: { host: '127.0.0.1', port: upstream.port, userId: 'u', password: 'p' },
      });
      expect(b.port).not.toBe(1090);
      // The same port can be reused safely because the listener is closed.
      // But more importantly, both ports are valid ephemeral ports and the
      // bridge chose them via listen(0), not a hardcoded constant.
      expect(b.port).toBeGreaterThan(0);
      expect(typeof portA).toBe('number');
      await b.close();
    } finally {
      await upstream.close();
    }
  });
});

/**
 * browser-skills E2E — exercise the full dispatch path against the bundled
 * `hackernews-frontpage` reference skill. Verifies:
 *
 *   - $B skill list resolves the bundled tier and surfaces hackernews-frontpage
 *   - $B skill show returns the SKILL.md
 *   - $B skill test runs script.test.ts (which itself runs against the bundled
 *     fixture) and reports pass
 *
 * Coverage gap intentionally NOT here: $B skill run end-to-end against the
 * bundled skill goes to live news.ycombinator.com and would be flaky. The
 * spawnSkill lifecycle (env scrub, scoped token, timeout, stdout cap) is
 * already covered by browse/test/browser-skill-commands.test.ts using inline
 * scripts.
 */

import { describe, test, expect, beforeAll } from 'bun:test';
import { handleSkillCommand } from '../src/browser-skill-commands';
import { listBrowserSkills, defaultTierPaths } from '../src/browser-skills';
import { initRegistry, __resetRegistry } from '../src/token-registry';

beforeAll(() => {
  // __resetRegistry zeroes rootToken so the new initRegistry mismatch guard
  // doesn't fire. rotateRoot would leave a UUID in rootToken and the next
  // initRegistry call would throw.
  __resetRegistry();
  initRegistry('e2e-root-token');
});

describe('browser-skills E2E — bundled hackernews-frontpage', () => {
  test('defaultTierPaths resolves bundled tier to <repo>/browser-skills/', () => {
    const tiers = defaultTierPaths();
    expect(tiers.bundled).toMatch(/\/browser-skills$/);
    // Bundled tier should exist on disk (the reference skill is shipped).
    expect(require('fs').existsSync(tiers.bundled)).toBe(true);
  });

  test('listBrowserSkills() returns hackernews-frontpage at bundled tier', () => {
    const skills = listBrowserSkills();
    const hn = skills.find(s => s.name === 'hackernews-frontpage');
    expect(hn).toBeTruthy();
    expect(hn!.tier).toBe('bundled');
    expect(hn!.frontmatter.host).toBe('news.ycombinator.com');
    expect(hn!.frontmatter.trusted).toBe(true);
    expect(hn!.frontmatter.triggers).toContain('scrape hn frontpage');
  });

  test('$B skill list dispatches and includes hackernews-frontpage', async () => {
    const result = await handleSkillCommand(['list'], { port: 0 });
    expect(result).toContain('hackernews-frontpage');
    expect(result).toContain('bundled');
    expect(result).toContain('news.ycombinator.com');
  });

  test('$B skill show hackernews-frontpage prints the SKILL.md', async () => {
    const result = await handleSkillCommand(['show', 'hackernews-frontpage'], { port: 0 });
    expect(result).toContain('host: news.ycombinator.com');
    expect(result).toContain('trusted: true');
    expect(result).toContain('Hacker News front-page scraper');
    expect(result).toContain('triggers:');
  });

  test('$B skill show <missing> errors clearly', async () => {
    await expect(handleSkillCommand(['show', 'nonexistent-skill-xyz'], { port: 0 }))
      .rejects.toThrow(/not found in any tier/);
  });

  test('$B skill help prints usage', async () => {
    const result = await handleSkillCommand([], { port: 0 });
    expect(result).toContain('Usage');
    expect(result).toContain('list');
    expect(result).toContain('show');
    expect(result).toContain('run');
  });

  test('$B skill rm cannot tombstone bundled tier (read-only)', async () => {
    // The bundled hackernews-frontpage skill is shipped read-only; rm targets
    // user tiers (project default, --global). Attempting rm on a name that
    // only exists in bundled should error with "not found".
    await expect(handleSkillCommand(['rm', 'hackernews-frontpage', '--global'], { port: 0 }))
      .rejects.toThrow(/not found/);
  });

  // The `test` subcommand spawns `bun test script.test.ts` in the skill dir.
  // It takes ~1s. Run it last so other assertions are quick.
  test('$B skill test hackernews-frontpage runs script.test.ts and reports pass', async () => {
    const result = await handleSkillCommand(['test', 'hackernews-frontpage'], { port: 0 });
    // `bun test` splits its report across streams: the version banner goes to
    // stdout, the pass/fail summary to stderr. handleSkillCommand must return
    // both, so assert on each stream's half.
    //
    // This used to flake under full-suite load: capturing the child through
    // pipes dropped stderr on the first piped spawn in the process, so the
    // result was just the banner. The old `13 pass|0 fail|tests passed` regex
    // also had a `tests passed` alternative that matched a synthetic fallback
    // string, which would have passed vacuously on an empty capture.
    expect(result).toMatch(/bun test v/); // stdout half
    expect(result).toMatch(/\b0 fail\b/); // stderr half
    expect(result).toMatch(/Ran \d+ tests/);
  }, 30_000);
});

import * as crypto from "node:crypto"
import * as fs from "node:fs"
import * as os from "node:os"
import * as path from "node:path"
import { afterEach, beforeEach, describe, expect, it } from "vitest"
import {
  BANNER,
  ambiguityNotice,
  buildContext,
  checkComplete,
  countSelectablePlans,
  effectiveProjectRoot,
  evaluateGate,
  gateCounts,
  initPlan,
  ledgerLineCount,
  modeTokens,
  nestedLivePlans,
  resolvePlan,
  slugIsValid,
  summarizeStatus,
  verifyPlan,
} from "../src/core.js"

const GATED_PLAN = [
  "# Task Plan: Night run",
  "",
  "## Goal",
  "",
  "Ship it.",
  "",
  "### Phase 1: Discovery",
  "- [x] read",
  "- **Status:** complete",
  "",
  "### Phase 2: Build the adapter",
  "- [ ] write",
  "- **Status:** in_progress",
  "",
  "### Phase 3: Release",
  "- [ ] tag",
  "- **Status:** pending",
  "",
].join("\n")

let root: string
let env: Record<string, string | undefined>

function sha(file: string): string {
  return crypto.createHash("sha256").update(fs.readFileSync(file)).digest("hex")
}

function slugPlan(
  base: string,
  slug: string,
  opts: { text?: string; mode?: string; attest?: boolean; pointer?: boolean } = {},
): string {
  const dir = path.join(base, ".planning", slug)
  fs.mkdirSync(dir, { recursive: true })
  fs.writeFileSync(path.join(dir, "task_plan.md"), opts.text ?? GATED_PLAN)
  fs.writeFileSync(path.join(dir, "progress.md"), "# Progress\n- started 2026-09-02T12:34:56Z\n")
  fs.writeFileSync(path.join(dir, "findings.md"), "# Findings\n")
  if (opts.mode !== undefined) fs.writeFileSync(path.join(dir, ".mode"), `${opts.mode}\n`)
  if (opts.attest) fs.writeFileSync(path.join(dir, ".attestation"), `${sha(path.join(dir, "task_plan.md"))}\n`)
  if (opts.pointer) fs.writeFileSync(path.join(base, ".planning", ".active_plan"), `${slug}\n`)
  return dir
}

beforeEach(() => {
  root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "pwf-oc-")))
  const home = path.join(root, "home")
  fs.mkdirSync(home)
  env = { HOME: home, USERPROFILE: home, XDG_CONFIG_HOME: path.join(home, ".config") }
})

afterEach(() => {
  fs.rmSync(root, { recursive: true, force: true })
})

describe("resolver", () => {
  it("prefers the .active_plan pointer over a legacy root plan, and falls back to root", () => {
    fs.writeFileSync(path.join(root, "task_plan.md"), "# ROOT\n")
    const slug = slugPlan(root, "2026-09-02-night", { pointer: true })
    expect(resolvePlan(root, {}, env)).toEqual({ planDir: slug, conflicts: [] })
    fs.rmSync(path.join(root, ".planning"), { recursive: true })
    expect(resolvePlan(root, {}, env).planDir).toBe(root)
  })

  it("rejects invalid slugs from the pointer and from PLAN_ID", () => {
    fs.writeFileSync(path.join(root, "task_plan.md"), "# ROOT\n")
    fs.mkdirSync(path.join(root, ".planning"))
    for (const bad of ["../outside", "bad slug", "/abs", ".hidden"]) {
      fs.writeFileSync(path.join(root, ".planning", ".active_plan"), `${bad}\n`)
      expect(resolvePlan(root, {}, env).planDir).toBe(root)
      // a rejected PLAN_ID stops resolution instead of falling through to the
      // pointer, the newest slug or the legacy root (#237)
      expect(resolvePlan(root, {}, { ...env, PLAN_ID: bad }).planDir).toBeNull()
    }
    expect(slugIsValid("-leading")).toBe(false)
    expect(slugIsValid("2026-09-02-run.v2")).toBe(true)
  })

  it("stops when a valid-shape PLAN_ID names no directory, ignoring the pointer (#237)", () => {
    const active = slugPlan(root, "2026-09-02-active", { pointer: true })
    expect(resolvePlan(root, {}, env).planDir).toBe(active)
    // one typo in the slug: the pointed plan must NOT answer in its place
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-actve" })).toEqual({
      planDir: null,
      conflicts: [],
    })
    // an empty PLAN_ID is still "no selector" and resolves the pointer
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "" }).planDir).toBe(active)
  })

  it("resolves a single named plan without a pointer, and PLAN_ID selects among several", () => {
    const only = slugPlan(root, "2026-09-02-only")
    expect(resolvePlan(root, {}, env).planDir).toBe(only)
    const older = slugPlan(root, "2026-08-01-old")
    const past = new Date(Date.now() - 3_600_000)
    fs.utimesSync(path.join(older, "task_plan.md"), past, past)
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-08-01-old" }).planDir).toBe(older)
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-only" }).planDir).toBe(only)
  })

  it("refuses several named plans without PLAN_ID, pointer or pin notwithstanding (#240)", () => {
    const a = slugPlan(root, "2026-09-02-a", { pointer: true })
    slugPlan(root, "2026-09-02-b")
    expect(resolvePlan(root, {}, env)).toEqual({ planDir: null, conflicts: [], multiple: true })
    expect(resolvePlan(root, { explicit: true }, env)).toEqual({ planDir: null, conflicts: [], multiple: true })
    expect(countSelectablePlans(root)).toBe(2)
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-a" }).planDir).toBe(a)
    // a directory without task_plan.md and a dot-named directory do not count
    fs.mkdirSync(path.join(root, ".planning", "sessions"))
    fs.mkdirSync(path.join(root, ".planning", ".archive"))
    fs.writeFileSync(path.join(root, ".planning", ".archive", "task_plan.md"), "# OLD\n")
    fs.rmSync(path.join(root, ".planning", "2026-09-02-b"), { recursive: true })
    expect(countSelectablePlans(root)).toBe(1)
    expect(resolvePlan(root, {}, env).planDir).toBe(a)
    // an armed sessions directory makes a root plan count as one more
    fs.writeFileSync(path.join(root, "task_plan.md"), "# ROOT\n")
    expect(countSelectablePlans(root)).toBe(2)
    expect(resolvePlan(root, {}, env).multiple).toBe(true)
  })

  it("tolerates a UTF-8 BOM in the pointer", () => {
    // With one named plan the pointer names it; a BOM must not turn that
    // into an invalid slug that ends resolution.
    const older = slugPlan(root, "2026-08-01-aaa")
    fs.writeFileSync(path.join(root, "task_plan.md"), "# ROOT\n")
    fs.writeFileSync(path.join(root, ".planning", ".active_plan"), Buffer.from("﻿2026-08-01-aaa\r\n", "utf8"))
    expect(resolvePlan(root, {}, env).planDir).toBe(older)
  })

  it("only a live nested plan makes a cwd guess ambiguous, and explicit selection skips the check", () => {
    const parent = slugPlan(root, "2026-09-02-parent", { pointer: true })
    const service = path.join(root, "service")
    fs.mkdirSync(path.join(service, ".planning"), { recursive: true })
    fs.writeFileSync(path.join(service, "task_plan.md"), "# loose\n")
    fs.writeFileSync(path.join(service, ".planning", ".active_plan"), "gone\n")
    expect(nestedLivePlans(root)).toEqual([])
    expect(resolvePlan(root, {}, env)).toEqual({ planDir: parent, conflicts: [] })
    fs.mkdirSync(path.join(service, ".planning", "2026-09-02-child"))
    fs.writeFileSync(path.join(service, ".planning", "2026-09-02-child", "task_plan.md"), "# CHILD\n")
    expect(resolvePlan(root, {}, env)).toEqual({ planDir: null, conflicts: ["service"] })
    expect(resolvePlan(root, { explicit: true }, env).planDir).toBe(parent)
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-parent" }).planDir).toBe(parent)
    expect(ambiguityNotice(["service"])).toContain("(service)")
  })

  it("guards a legacy root plan the same way", () => {
    fs.writeFileSync(path.join(root, "task_plan.md"), "# PARENT\n")
    fs.mkdirSync(path.join(root, "projectx", ".planning", "2026-09-02-x"), { recursive: true })
    fs.writeFileSync(path.join(root, "projectx", ".planning", "2026-09-02-x", "task_plan.md"), "# X\n")
    expect(resolvePlan(root, {}, env)).toEqual({ planDir: null, conflicts: ["projectx"] })
  })

  it("refuses a slug directory that escapes .planning through a link, and a linked task_plan.md", () => {
    const outside = path.join(root, "outside")
    fs.mkdirSync(outside)
    fs.writeFileSync(path.join(outside, "task_plan.md"), "# OUTSIDE\n")
    const planning = path.join(root, ".planning")
    fs.mkdirSync(planning)
    try {
      fs.symlinkSync(outside, path.join(planning, "2026-09-02-evil"), "junction")
    } catch {
      return // no privilege to create links on this box; the guard is exercised on CI
    }
    fs.writeFileSync(path.join(planning, ".active_plan"), "2026-09-02-evil\n")
    expect(resolvePlan(root, {}, env).planDir).toBeNull()
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-evil" }).planDir).toBeNull()
    // a linked plan directory never counts toward the several-plans rule (#270)
    expect(countSelectablePlans(root)).toBe(0)
    const real = path.join(planning, "2026-09-02-real")
    fs.mkdirSync(real)
    fs.writeFileSync(path.join(real, "task_plan.md"), "# REAL\n")
    expect(countSelectablePlans(root)).toBe(1)
    expect(resolvePlan(root, {}, env).planDir).toBe(real)
    fs.rmSync(path.join(real, "task_plan.md"))
    try {
      fs.symlinkSync(path.join(outside, "task_plan.md"), path.join(real, "task_plan.md"), "file")
    } catch {
      return
    }
    expect(resolvePlan(root, {}, { ...env, PLAN_ID: "2026-09-02-real" }).planDir).toBeNull()
  })

  it("counts ledger lines like grep -c, including empty lines", () => {
    const dir = slugPlan(root, "2026-09-02-run", { mode: "autonomous gate", attest: true, pointer: true })
    fs.writeFileSync(path.join(dir, "ledger-main.jsonl"), '{"a":1}\n\n{"b":2}\n')
    expect(ledgerLineCount(dir)).toBe(3)
    fs.writeFileSync(path.join(dir, "ledger-worker.jsonl"), '{"c":3}')
    expect(ledgerLineCount(dir)).toBe(4)
  })

  it("applies the PWF_PLAN_ROOT pin and fails closed on a broken pin", () => {
    const project = path.join(root, "project")
    fs.mkdirSync(project)
    expect(effectiveProjectRoot(root, { ...env, PWF_PLAN_ROOT: project })).toBe(fs.realpathSync(project))
    expect(effectiveProjectRoot(root, { ...env, PWF_PLAN_ROOT: path.join(root, "missing") })).toBeNull()
    expect(effectiveProjectRoot(root, { ...env, PWF_PLAN_ROOT: "relative/path" })).toBeNull()
    if (process.platform === "win32") expect(effectiveProjectRoot(root, { ...env, PWF_PLAN_ROOT: "\\rootless" })).toBeNull()
    expect(effectiveProjectRoot(root, env)).toBe(root)
  })
})

describe("injection", () => {
  it("frames a legacy root plan with the banner and no plan line", () => {
    fs.writeFileSync(path.join(root, "task_plan.md"), "# Plan\n- **Status:** in_progress\n")
    fs.writeFileSync(path.join(root, "progress.md"), "- started 2026-09-02T12:34:56Z\n")
    const context = buildContext(root, root)
    expect(context.startsWith(`${BANNER}\n\n`)).toBe(true)
    expect(context).toContain("===BEGIN-PWF-DATA kind=plan nonce=")
    expect(context).toContain("kind=progress")
    expect(context).toContain("T00:00:00Z")
    expect(context).not.toContain("T12:34:56Z")
    expect(context).not.toContain("[planning-with-files] plan:")
  })

  it("names a slug plan, honours its attestation, and refuses tampered or unattested v3 plans", () => {
    const dir = slugPlan(root, "2026-09-02-run", { mode: "autonomous", attest: true, pointer: true })
